"""Pydantic schemas for the HTTP API and for tool inputs/outputs."""

from __future__ import annotations

from typing import Annotated, Literal

from pydantic import BaseModel, ConfigDict, Field

# Identifiers are generated by the server (prefix + url-safe random token) or,
# for sessions/conversations, by the browser (UUID). Both fit this pattern, and
# the pattern excludes path separators and dots by construction.
ID_PATTERN = r"^[A-Za-z0-9_-]{8,80}$"


# --- Chat ----------------------------------------------------------------


class HistoryMessage(BaseModel):
    """A previous turn, as remembered by the browser.

    Only text and *identifiers* travel through the client. Tool results are
    re-read from the server-side store by id, so a client cannot forge them.
    """

    model_config = ConfigDict(extra="ignore")

    role: Literal["user", "assistant"]
    text: str = Field(default="", max_length=40_000)
    attachment_ids: list[str] = Field(default_factory=list, max_length=8)
    tool_result_ids: list[str] = Field(default_factory=list, max_length=8)


class CurrentMessage(BaseModel):
    model_config = ConfigDict(extra="ignore")

    text: str = Field(default="", max_length=20_000)
    attachment_ids: list[str] = Field(default_factory=list, max_length=8)


class ChatRequest(BaseModel):
    model_config = ConfigDict(extra="ignore")

    conversation_id: str = Field(pattern=ID_PATTERN)
    consent: bool = False
    history: list[HistoryMessage] = Field(default_factory=list, max_length=400)
    message: CurrentMessage


# --- Uploads -------------------------------------------------------------


class UploadResponse(BaseModel):
    image_id: str
    filename: str
    width: int
    height: int
    size_bytes: int
    media_type: Literal["image", "pdf"] = "image"
    pages: int = 1
    # What the local vision transformer saw in the picture (PDFs are "document").
    content: Literal["xray", "scan", "document", "photo", "unknown"] = "unknown"
    content_confidence: float = 0.0
    expires_in_seconds: int


# --- Health --------------------------------------------------------------


class YoloHealth(BaseModel):
    status: Literal["ready", "not_configured", "weights_missing", "incompatible", "error"]
    detail: str
    classes: list[str] = Field(default_factory=list)


class ImageTriageHealth(BaseModel):
    status: Literal["ready", "loading", "disabled", "not_installed", "error"]
    detail: str
    model: str


class HealthResponse(BaseModel):
    status: Literal["ok"]
    claude_configured: bool
    # ".env" or "environment": a variable in the launching shell overrides the file.
    claude_key_source: Literal[".env", "environment", "none"] = "none"
    claude_model: str
    yolo: YoloHealth
    image_triage: ImageTriageHealth
    tools: list[str]


# --- analyze_xray tool ---------------------------------------------------


class AnalyzeXrayInput(BaseModel):
    """Input Claude may supply. Only an opaque identifier — never a path."""

    model_config = ConfigDict(extra="forbid")

    image_id: str = Field(pattern=ID_PATTERN)


class ReadDocumentInput(BaseModel):
    """Only the identifier of a file uploaded in this conversation."""

    model_config = ConfigDict(extra="forbid")

    image_id: str = Field(pattern=ID_PATTERN)


class FindDoctorsInput(BaseModel):
    """Free text only; the server maps it onto Superdoc's own catalog."""

    model_config = ConfigDict(extra="forbid")

    specialty: str = Field(min_length=2, max_length=60)
    city: str | None = Field(default=None, max_length=60)
    sort: Literal["popular", "rating", "earliest"] = "popular"


class LookupMedicationInput(BaseModel):
    """Medication names only; the server builds every Framar URL itself."""

    model_config = ConfigDict(extra="forbid")

    medications: list[Annotated[str, Field(min_length=2, max_length=60)]] = Field(min_length=1, max_length=6)


class Detection(BaseModel):
    class_name: str
    score: float
    bbox: list[int]  # [x1, y1, x2, y2] in pixels of the original image
